int 
dtb_mainwin_remove_mbar_msg_initialize(DtbMessageData instance)
{
    char	*tmp_txt;
    if (instance->initialized)
    {
        return 0;
    }
    instance->initialized = True;

    instance->type = XmDIALOG_WARNING;
    instance->title = XmStringCreateLocalized(CATGETS(Dtb_project_catd, 21, 27, "Application Builder"));
    instance->message = XmStringCreateLocalized(CATGETS(Dtb_project_catd, 21, 28, "Removing Menubar will cause all\nMenubar children to be deleted."));
    instance->action1_label = XmStringCreateLocalized(CATGETS(Dtb_project_catd, 21, 29, "Remove"));
    instance->action1_callback = (XtCallbackProc) NULL;
    instance->action2_label = (XmString) NULL;
    instance->action2_callback = (XtCallbackProc) NULL;
    instance->action3_label = (XmString) NULL;
    instance->action3_callback = (XtCallbackProc) NULL;
    instance->cancel_button = True;
    instance->cancel_callback = (XtCallbackProc) NULL;
    instance->help_button = True;
    tmp_txt = CATGETS(Dtb_project_catd, 21, 54, "If the menubar is removed, any changes made to\nthe menubar (additional menubar items) will also\nbe deleted. You have the option of continuing\nwith the deletion or cancelling the operation.");
    instance->help_data.help_text = XtMalloc(strlen(tmp_txt)+1);
    strcpy(instance->help_data.help_text, tmp_txt);
    
    instance->help_data.help_volume = "";
    instance->help_data.help_locationID = "";
    instance->default_button = DTB_CANCEL_BUTTON;
    return 0;
}

